def grep(txt,pats,w=220):
    out=[]
    for p in pats:
        for m in list(re.finditer(p,txt))[:2]:
            out.append("  ["+p+"] "+txt[max(0,m.start()-40):m.start()+w].replace("\n"," "))
    return out
